package com.fynx.app.ui

import android.content.Context
import android.net.Uri
import org.json.JSONArray
import org.json.JSONObject
import java.net.URLEncoder
import java.util.Locale

object FynxRemoteSocialClient {
    data class RemotePost(val id:String,val authorId:String,val authorUsername:String,val authorDisplayName:String,val text:String,val visibility:String,val mediaId:String?,val mediaType:String?,val mediaUrl:String?,val timestamp:Long,val likeCount:Int,val commentCount:Int,val likedByCurrentUser:Boolean,val followedByCurrentUser:Boolean)
    data class FeedPage(val posts:List<RemotePost>,val hasMore:Boolean)
    data class RemoteComment(val id:String,val text:String,val timestamp:Long,val authorId:String,val authorUsername:String,val authorDisplayName:String)
    data class RemoteUser(val id:String,val username:String,val displayName:String)
    data class MarketplaceListing(val id:String,val sellerId:String,val sellerUsername:String,val sellerDisplayName:String,val storeName:String,val title:String,val description:String,val price:Double,val currency:String,val category:String,val condition:String,val quantity:Int,val location:String,val deliveryAvailable:Boolean,val pickupAvailable:Boolean,val deliveryFee:Double?,val mediaIds:List<String>,val active:Boolean=true)
    data class MarketplaceOrder(val id:String,val buyerId:String,val sellerId:String,val listingId:String,val quantity:Int,val unitPrice:Double,val deliveryFee:Double,val totalAmount:Double,val currency:String,val productTitle:String,val sellerUsername:String?,val status:String,val trackingReference:String?,val fulfillmentMethod:String,val shippingAddress:JSONObject?,val buyerNote:String,val inspectionDeadline:String?,val deliveryAvailable:Boolean,val pickupAvailable:Boolean)
    private const val FEED_PAGE_SIZE=20
    private const val FEED_CACHE_TTL_MS=120_000L
    private const val FEED_CACHE_KEY="fynx_feed_cache_v1"
    private const val FEED_CACHE_TIME_KEY="fynx_feed_cache_time_v1"
    suspend fun feed(context:Context):Result<List<RemotePost>>=feedPage(context,FEED_PAGE_SIZE,0,true).map{it.posts}
    suspend fun feedPage(context:Context,limit:Int=FEED_PAGE_SIZE,offset:Int=0,useCache:Boolean=false):Result<FeedPage>{
        val safeLimit=limit.coerceIn(1,FEED_PAGE_SIZE);val safeOffset=offset.coerceAtLeast(0)
        if(useCache&&safeOffset==0)readCachedFeed(context)?.let{return Result.success(it)}
        val remote=FynxBackendClient.get(context,"/api/social/feed?limit=$safeLimit&offset=$safeOffset").mapCatching{raw->parseFeedPage(raw).also{if(safeOffset==0)writeCachedFeed(context,raw)}}
        if(safeOffset==0&&remote.isFailure)readStaleCachedFeed(context)?.let{return Result.success(it)}
        return remote
    }
    private fun parseFeedPage(raw:String):FeedPage{val root=JSONObject(raw);val array=root.optJSONArray("posts")?:JSONArray();val posts=buildList{for(i in 0 until array.length()){val o=array.getJSONObject(i);add(RemotePost(o.optString("id"),o.optString("authorId"),o.optString("authorUsername"),o.optString("authorDisplayName"),o.optString("text"),o.optString("visibility"),o.optString("mediaId").takeIf{it.isNotBlank()&&it!="null"},o.optString("mediaType").takeIf{it.isNotBlank()&&it!="null"},o.optString("mediaUrl").takeIf{it.isNotBlank()},o.optDouble("timestamp",0.0).toLong(),o.optInt("likeCount"),o.optInt("commentCount"),o.optBoolean("likedByCurrentUser"),o.optBoolean("followedByCurrentUser")))}};return FeedPage(posts,root.optBoolean("hasMore",posts.size>=FEED_PAGE_SIZE))}
    private fun readCachedFeed(context:Context):FeedPage?=runCatching{val p=context.getSharedPreferences("fynx_feed_cache",Context.MODE_PRIVATE);val raw=p.getString(FEED_CACHE_KEY,null)?:return null;if(System.currentTimeMillis()-p.getLong(FEED_CACHE_TIME_KEY,0L)>FEED_CACHE_TTL_MS)return null;parseFeedPage(raw)}.getOrNull()
    private fun readStaleCachedFeed(context:Context):FeedPage?=runCatching{val p=context.getSharedPreferences("fynx_feed_cache",Context.MODE_PRIVATE);p.getString(FEED_CACHE_KEY,null)?.let(::parseFeedPage)}.getOrNull()
    private fun writeCachedFeed(context:Context,raw:String){runCatching{context.getSharedPreferences("fynx_feed_cache",Context.MODE_PRIVATE).edit().putString(FEED_CACHE_KEY,raw).putLong(FEED_CACHE_TIME_KEY,System.currentTimeMillis()).apply()}}

    suspend fun createPost(context:Context,text:String,visibility:FynxPostVisibility,uri:Uri?):Result<Unit>=runCatching{
        val cleanText=text.trim()
        require(cleanText.isNotBlank()||uri!=null){"Write something or select media."}
        val media=uri?.let{sourceUri->val mime=mediaMimeType(context,sourceUri);val type=when{mime.startsWith("image/")->"image";mime.startsWith("video/")->"video";mime.startsWith("audio/")->"audio";else->throw IllegalArgumentException("Select an image, video or audio.")};FynxProductionMessaging.uploadMedia(context,sourceUri,mime).getOrThrow() to type}
        val body=JSONObject().apply{put("text",cleanText);put("visibility",visibility.name);put("mediaId",media?.first?.id?:JSONObject.NULL);put("mediaType",media?.second?:JSONObject.NULL)}.toString()
        FynxBackendClient.postJson(context,"/api/social/posts",body).getOrThrow();Unit
    }
    private fun mediaMimeType(context:Context,uri:Uri):String{context.contentResolver.getType(uri)?.lowercase()?.takeIf{it.isNotBlank()}?.let{return it};val path=uri.path?.lowercase().orEmpty();return when{path.endsWith(".jpg")||path.endsWith(".jpeg")->"image/jpeg";path.endsWith(".png")->"image/png";path.endsWith(".webp")->"image/webp";path.endsWith(".heic")||path.endsWith(".heif")->"image/heif";path.endsWith(".mp4")->"video/mp4";path.endsWith(".3gp")->"video/3gpp";path.endsWith(".webm")->"video/webm";path.endsWith(".m4a")->"audio/mp4";path.endsWith(".aac")->"audio/aac";path.endsWith(".mp3")->"audio/mpeg";path.endsWith(".wav")->"audio/wav";else->""}}

    suspend fun createMarketplaceAd(context:Context,listingId:String,title:String,description:String,storeName:String,price:Double,currency:String,mediaId:String?):Result<Unit>{val priceText="${currency.trim().uppercase()} ${String.format(Locale.US,"%,.2f",price)}";val text="[FYNX_MARKETPLACE_AD]\n🛍️ ${title.trim().take(120)}\nPrice: $priceText\nStore: ${storeName.trim().take(120)}\n${description.trim().take(1000)}\nListing ID: $listingId";return FynxBackendClient.postJson(context,"/api/social/posts",JSONObject().apply{put("text",text.take(4000));put("visibility","PUBLIC");put("mediaId",mediaId?:JSONObject.NULL);put("mediaType",if(mediaId!=null)"image" else JSONObject.NULL)}.toString()).map{Unit}}
    suspend fun listings(context:Context,query:String="",category:String="All",seller:String=""):Result<List<MarketplaceListing>>=FynxBackendClient.get(context,"/api/marketplace/listings?q=${URLEncoder.encode(query,"UTF-8")}&category=${URLEncoder.encode(category,"UTF-8")}&seller=${URLEncoder.encode(seller.removePrefix("@"),"UTF-8")}").mapCatching(::parseListings)
    suspend fun myListings(context:Context):Result<List<MarketplaceListing>>=FynxBackendClient.get(context,"/api/marketplace/my-listings").mapCatching(::parseListings)
    suspend fun createMarketplaceListing(context:Context,title:String,description:String,storeName:String,price:Double,currency:String,category:String,condition:String,quantity:Int,location:String,deliveryAvailable:Boolean,pickupAvailable:Boolean,deliveryFee:Double?,mediaUris:List<Uri>):Result<MarketplaceListing?>=runCatching{
        require(title.trim().length>=2){"Product name is required."};require(description.trim().length>=5){"Add a product description."};require(price.isFinite()&&price>0){"Enter a valid product price."};require(quantity>0){"Product quantity must be at least 1."};require(mediaUris.isNotEmpty()){ "Add at least one product photo or video." }
        val mediaIds=mediaUris.distinct().take(12).map{u->val mime=mediaMimeType(context,u);require(mime.startsWith("image/")||mime.startsWith("video/")){"Marketplace media must be an image or video."};FynxProductionMessaging.uploadMedia(context,u,mime).getOrThrow().id}
        val raw=FynxBackendClient.postJson(context,"/api/marketplace/listings",JSONObject().apply{put("title",title.trim());put("description",description.trim());put("storeName",storeName.trim());put("price",price);put("currency",currency.trim().uppercase());put("category",category.trim());put("condition",condition.trim().uppercase());put("quantity",quantity);put("location",location.trim());put("deliveryAvailable",deliveryAvailable);put("pickupAvailable",pickupAvailable);put("deliveryFee",deliveryFee?:JSONObject.NULL);put("mediaIds",JSONArray(mediaIds))}.toString()).getOrThrow();val id=JSONObject(raw).getJSONObject("listing").optString("id");listings(context).getOrNull()?.firstOrNull{it.id==id}}
    suspend fun deleteMarketplaceListing(context:Context,id:String):Result<Unit>{val numericId=id.toLongOrNull()?:return Result.failure(IllegalArgumentException("invalid listing id"));return FynxBackendClient.delete(context,"/api/marketplace/listings/$numericId").map{Unit}}
    suspend fun createMarketplaceOrder(context:Context,listingId:String,quantity:Int):Result<MarketplaceOrder>{val numericId=listingId.toLongOrNull()?:return Result.failure(IllegalArgumentException("invalid listing id"));require(quantity>0){"Quantity must be at least 1."};return FynxBackendClient.postJson(context,"/api/marketplace/orders",JSONObject().apply{put("listingId",numericId);put("quantity",quantity);put("orderId",java.util.UUID.randomUUID().toString())}.toString()).mapCatching{parseOrder(JSONObject(it).getJSONObject("order"))}}
    suspend fun orders(context:Context):Result<List<MarketplaceOrder>>=FynxBackendClient.get(context,"/api/marketplace/orders").mapCatching{raw->val a=JSONObject(raw).optJSONArray("orders")?:JSONArray();buildList{for(i in 0 until a.length())add(parseOrder(a.getJSONObject(i)))}}
    private fun parseOrder(o:JSONObject):MarketplaceOrder{val p=o.optJSONObject("product");return MarketplaceOrder(o.optString("id"),o.optString("buyerId"),o.optString("sellerId"),o.optString("listingId"),o.optInt("quantity"),o.optDouble("unitPrice"),o.optDouble("deliveryFee"),o.optDouble("totalAmount"),o.optString("currency","NGN"),p?.optString("title").orEmpty().ifBlank{o.optString("productTitle")},o.optString("sellerUsername").takeIf{it.isNotBlank()}?:p?.optString("sellerUsername")?.takeIf{it.isNotBlank()},o.optString("status"),o.optString("trackingReference").takeIf{it.isNotBlank()},o.optString("fulfillmentMethod","DELIVERY"),o.optJSONObject("shippingAddress"),o.optString("buyerNote"),o.optString("inspectionDeadline").takeIf{it.isNotBlank()},p?.optBoolean("deliveryAvailable",false)?:false,p?.optBoolean("pickupAvailable",false)?:false)}
    suspend fun setMarketplaceFulfillment(context:Context,id:String,method:String,name:String="",phone:String="",address:String="",city:String="",state:String="",country:String="",buyerNote:String=""):Result<Unit>{val safe=method.trim().uppercase();require(safe=="DELIVERY"||safe=="PICKUP"){"Choose delivery or pickup."};if(safe=="DELIVERY")require(name.trim().isNotBlank()&&phone.trim().isNotBlank()&&address.trim().isNotBlank()){ "Name, phone and delivery address are required." };val shipping=if(safe=="DELIVERY")JSONObject().apply{put("name",name.trim().take(120));put("phone",phone.trim().take(40));put("address",address.trim().take(500));put("city",city.trim().take(100));put("state",state.trim().take(100));put("country",country.trim().take(100))}else JSONObject.NULL;return FynxBackendClient.postJson(context,"/api/marketplace/orders/$id/fulfillment",JSONObject().apply{put("method",safe);put("shippingAddress",shipping);put("buyerNote",buyerNote.trim().take(500))}.toString()).map{Unit}}
    private fun parseListings(raw:String):List<MarketplaceListing>{val a=JSONObject(raw).optJSONArray("listings")?:JSONArray();return buildList{for(i in 0 until a.length()){val o=a.getJSONObject(i);val ids=o.optJSONArray("mediaIds")?:JSONArray();add(MarketplaceListing(o.optString("id"),o.optString("sellerId"),o.optString("sellerUsername"),o.optString("sellerDisplayName"),o.optString("storeName"),o.optString("title"),o.optString("description"),o.optDouble("price"),o.optString("currency","NGN"),o.optString("category"),o.optString("condition"),o.optInt("quantity"),o.optString("location"),o.optBoolean("deliveryAvailable"),o.optBoolean("pickupAvailable"),if(o.has("deliveryFee")&&!o.isNull("deliveryFee"))o.optDouble("deliveryFee")else null,buildList{for(j in 0 until ids.length())add(ids.optString(j))},o.optBoolean("active",true)))}}
}